# Step 3: review submission page + API. Validates the review token
# server-side, shows a star picker + comment form, and on submit
# saves the review, marks the token used, and recalculates the
# product's aggregate rating.

New-Item -ItemType Directory -Force -Path "src\app\review\[token]" | Out-Null
New-Item -ItemType Directory -Force -Path "src\app\api\reviews\submit" | Out-Null

$bytes = [System.Convert]::FromBase64String("")
[System.IO.File]::WriteAllBytes((Join-Path (Get-Location) "src\app\review\[token]\page.tsx"), $bytes)
Write-Host "NEW: src\app\review\[token]\page.tsx" -ForegroundColor Green

$bytes = [System.Convert]::FromBase64String("")
[System.IO.File]::WriteAllBytes((Join-Path (Get-Location) "src\app\review\[token]\ReviewSubmissionForm.tsx"), $bytes)
Write-Host "NEW: src\app\review\[token]\ReviewSubmissionForm.tsx" -ForegroundColor Green

$bytes = [System.Convert]::FromBase64String("")
[System.IO.File]::WriteAllBytes((Join-Path (Get-Location) "src\app\api\reviews\submit\route.ts"), $bytes)
Write-Host "NEW: src\app\api\reviews\submit\route.ts" -ForegroundColor Green

Write-Host "`nAll 3 files written." -ForegroundColor Cyan
Write-Host "Now run: npx tsc --noEmit" -ForegroundColor Cyan